insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-9453')::uuid, md5('building-spohrstrasse-2-6-22083')::uuid, '9453', 'grosszuegige-bueroflaeche-in-winterhude-9453', 'Großzügige Bürofläche in Winterhude', 'Das markante Bürogebäude befindet sich zwischen dem Stadtpark und der Außenalster nahe dem Osterbekkanal. Diverse U-Bahn- oder Buslinien sind schnell erreicht. Die helle …', 'Das markante Bürogebäude befindet sich zwischen dem Stadtpark und der Außenalster nahe dem Osterbekkanal. Diverse U-Bahn- oder Buslinien sind schnell erreicht. Die helle Bürofläche ist momentan mit Teppich- und teilweise Linoleumfußboden, Fensterbrüstungskanäle, Beleuchtungssystemen sowie Trennwänden mit Glasausschnitten ausgestattet. Eine Pantry sowie getrennte WC-Einheiten sind vorhanden. Das Gebäude verfügt neben einem Personenaufzug auch über einen Lastenaufzug. Ausreichend PKW-Stellplätze können im Hof oder der hauseigenen Tiefgarage angemietet werden. Diese Bilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], 310, 1218, 'https://www.buerohamburg.de/objects/pdf/BHI_9453.pdf', null, 'filemaker', '9453') on conflict (id) do nothing;
