insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-11178')::uuid, md5('building-schellerdamm-18-21079')::uuid, '11178', 'moderne-bueroflaechen-direkt-am-wasser-11178', 'Moderne Büroflächen direkt am Wasser', 'Das moderne Bürogebäude befindet sich nahe der Harburger Innenstadt, nur wenige Gehminuten von der S-Bahnhaltestelle Harburg entfernt. Das Umfeld bietet eine große Auswahl an …', 'Das moderne Bürogebäude befindet sich nahe der Harburger Innenstadt, nur wenige Gehminuten von der S-Bahnhaltestelle Harburg entfernt. Das Umfeld bietet eine große Auswahl an Gastronomie und Einkaufsmöglichkeiten, weit über den täglichen Bedarf hinaus.  Die hellen Büroflächen können in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden und verfügen derzeit über in Bodentanks verlaufende EDV-Verkabelung sowie getrennte WC-Einheiten. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-11178-1')::uuid, md5('property-11178')::uuid, 'Mietfläche', 384, 14, null, 'filemaker', '11178-1') on conflict (id) do nothing;
