insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23776')::uuid, md5('building-schaeferkampsallee-16-18-20357')::uuid, '23776', 'individuell-ausgebaute-agenturflaeche-im-schlump-one-23776', 'Individuell ausgebaute Agenturfläche im Schlump One', 'Zwischen dem quirligen Schanzenviertel und dem belebten Universitätsquartier liegt dieses unverwechselbare Gewerbeobjekt. Das Schlump One wurde 2011 und 2012 umfangreich saniert …', 'Zwischen dem quirligen Schanzenviertel und dem belebten Universitätsquartier liegt dieses unverwechselbare Gewerbeobjekt. Das Schlump One wurde 2011 und 2012 umfangreich saniert und zu einem repräsentativen Bürogebäude umgebaut. Der U-Bahnhof Schlump sichert eine hervorragende Anbindung an den ÖPNV. Das Umfeld ist geprägt durch zahlreiche Grünanlagen, Restaurants, Cafés und diverse Einkaufsmöglichkeiten. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23776-1')::uuid, md5('property-23776')::uuid, 'Mietfläche', 384, 21, null, 'filemaker', '23776-1') on conflict (id) do nothing;
