insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25277')::uuid, md5('building-jungfernstieg-38-20354')::uuid, '25277', 'schoene-bueroflaeche-mit-alsterblick-im-streit-s-haus-25277', 'Schöne Bürofläche mit Alsterblick im Streit´s-Haus', 'Das repräsentative Büro- und Geschäftshaus befindet sich in bester Hamburger Innenstadtlage zwischen Binnenalster und Axel-Springer-Platz. Der Jungfernstieg mit allen U- und …', 'Das repräsentative Büro- und Geschäftshaus befindet sich in bester Hamburger Innenstadtlage zwischen Binnenalster und Axel-Springer-Platz. Der Jungfernstieg mit allen U- und S-Bahnanschlüssen sowie die Binnenalster sind fußläufig schnell erreicht. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants beleben die direkte Nachbarschaft. Die hier angebotene Bürofläche befindet sich im 1. OG mit Blick über die Binnenalster und wird über ein großzügig gestaltetes und repräsentatives Foyer mit zwei Personenaufzügen erschlossen. Die moderne Ausstattung umfasst aktuell unter anderem einen Teppichfußboden, eine Teeküche und separate Sanitäreinheiten. PKW-Stellplätze können in der unmittelbaren Umgebung angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['wasserblick']::text[], 146, 469, 'https://www.buerohamburg.de/objects/pdf/BHI_25277.pdf', null, 'filemaker', '25277') on conflict (id) do nothing;
