insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21831')::uuid, md5('building-oberbaumbruecke-1-20457')::uuid, '21831', 'ab-sofort-lichtdurchflutete-bueroflaeche-in-zentraler-citylage-21831', 'Ab sofort: lichtdurchflutete Bürofläche in zentraler Citylage', 'Das imposante Bürogebäude befindet sich in markanter Ecklage am Eingang zur HafenCity am Zollkanal. Der Hauptbahnhof, mit Anbindung an alle S- und U-Bahnlinien sowie die Züge der …', 'Das imposante Bürogebäude befindet sich in markanter Ecklage am Eingang zur HafenCity am Zollkanal. Der Hauptbahnhof, mit Anbindung an alle S- und U-Bahnlinien sowie die Züge der Deutschen Bahn, liegt nur wenige Fußminuten entfernt. Auch die U-Bahnstation Meßberg ist nach wenigen Metern erreicht. Im direkten Umfeld befinden sich zahlreiche Cafés und Restaurants und auch die Mönckebergstraße, mit Zugang zu allen Geschäften des täglichen Bedarfs, ist nach kurzem Fußweg erreicht.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-21831-1')::uuid, md5('property-21831')::uuid, 'Mietfläche', 392, 24.5, null, 'filemaker', '21831-1') on conflict (id) do nothing;
