insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8705')::uuid, md5('building-roedingsmarkt-20-20459')::uuid, '8705', 'exklusive-bueroflaeche-in-elbnaehe-8705', 'Exklusive Bürofläche in Elbnähe', 'Im bester Citylage, nahe der Elbe und der HafenCity, befindet sich dieses moderne 9-geschossige Geschäftsgebäude. Zahlreiche Geschäfte des täglichen Bedarfs, Restaurants und Cafés …', 'Im bester Citylage, nahe der Elbe und der HafenCity, befindet sich dieses moderne 9-geschossige Geschäftsgebäude. Zahlreiche Geschäfte des täglichen Bedarfs, Restaurants und Cafés sind fußläufig nach wenigen Minuten erreicht. Die nahe gelegenen U-Bahnstationen Rödingsmarkt und Baumwall sichern die Anbindung an das öffentliche Verkehrsnetz. Die attraktiven Büroflächen werden über einen aufwendigen Foyerbereich mit LED-Beleuchtung und Panorama-Glasaufzügen erschlossen. Zur Ausstattung der hochwertigen Mieteinheit zählen Teppich-/Amticobodenbelag, Glaselemente, Beleuchtungssysteme, Hohlraumboden mit einer bereits verlegten Cat. 7 Verkabelung, eine Pantry sowie getrennte WC-Einheiten. Eine große Dachterrasse kann von allen Mietern genutzt werden. PKW-Stellplätze können in der hauseigenen Tiefgarage oder im benachbarten Parkhaus angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], 170, 440, 'https://www.buerohamburg.de/objects/pdf/BHI_8705.pdf', null, 'filemaker', '8705') on conflict (id) do nothing;
