insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22598')::uuid, md5('building-offakamp-7-9-22529')::uuid, '22598', 'victoria-lofts-neubauerstbezug-zwischen-eppendorf-und-flughafen-22598', 'Victoria Lofts - Neubauerstbezug zwischen Eppendorf und Flughafen', 'Der imposante, in zwei Bauabschnitte geteilte Neubau befindet sich in verkehrsgünstiger Lage in Lokstedt in unmittelbarer Nachbarschaft zur BMW Hauptniederlassung. Der …', 'Der imposante, in zwei Bauabschnitte geteilte Neubau befindet sich in verkehrsgünstiger Lage in Lokstedt in unmittelbarer Nachbarschaft zur BMW Hauptniederlassung. Der Bauabschnitt zur Straßenseite Offakamp bietet neben flexibel teilbaren und lichtdurchfluteten Büros zwei großzügige Showroom-Flächen im EG mit einer lichten Deckenhöhe von über 6 Metern. Zur hochwertigen Ausstattung der sich darüber befindenden Büroflächen zählen u.a. ein Doppelboden, auf Wunsch Teppich- oder Vinylboden, außenliegender Sonnenschutz an der Südfassade, Glasfaseranschluss der Anbieter Telekom, Vodafone und Willy.tel, moderne und voll ausgestattete Teeküchen und separate WC-Einheiten. Der Ausbau erfolgt in individueller Absprache mit dem zukünftigen Mieter. PKW-Stellplätze (z.T. mit Wallboxen für E-Mobilität) können angemietet werden. Besonders hervorzuheben ist darüber hinaus der großzügige und aufwendig gestaltete Dachgarten auf dem vorderen Bauabschnitt, der von allen Mietern genutzt werden kann.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_22598.pdf', null, 'filemaker', '22598') on conflict (id) do nothing;
