insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-17720')::uuid, md5('building-versmannstrasse-2-20457')::uuid, '17720', 'in-erster-reihe-am-baakenhafen-der-campus-tower-17720', 'In erster Reihe am Baakenhafen - Der Campus Tower', 'Der futuristische Neubau des Campus Towers befindet sich in prominenter Lage zwischen Baaken- und Oberhafen. Die U-Bahnstation HafenCity Universität ist fußläufig schnell erreicht …', 'Der futuristische Neubau des Campus Towers befindet sich in prominenter Lage zwischen Baaken- und Oberhafen. Die U-Bahnstation HafenCity Universität ist fußläufig schnell erreicht und sichert eine gute Anbindung an das öffentliche Verkehrsnetz. Die nahe gelegenen Elbbrücken sorgen für eine schnelle Anbindung an die A1, A252 und A255. In den kommenden Jahren soll sich am Baakenhafen ein grünes, urbanes Dorf als gemischtes Wohn- Freizeits- und Arbeitsquartier entwickeln mit eigenem Frischemarkt, Einzelhandel und diversen gastronomischen Angeboten. Eine Kita und eine Grundschule sind ebenso geplant wie eine große Indoorsporthalle und ein Bildungs- und Familienzentrum. Die Fläche ist teilbar, wird im veredelten Rohbau übergeben und überzeugt mit hohen Decken und toller Sichtbarkeit durch große Schaufensterfronten.', 'laden-gastro', array['laden-gastro']::property_category[], 'laden', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3.6, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['erdgeschoss', 'stellplaetze']::text[], 398, 508, 'https://www.buerohamburg.de/objects/pdf/BHI_17720.pdf', null, 'filemaker', '17720') on conflict (id) do nothing;
