insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23053')::uuid, md5('building-luebecker-strasse-101-109-22087')::uuid, '23053', 'bueroflaeche-mit-guter-verkehrsanbindung-in-hohenfelde-23053', 'Bürofläche mit guter Verkehrsanbindung in Hohenfelde', 'Das zentral gelegene Büro- und Geschäftsgebäude befindet sich nahe des Marienkankenhauses im Stadtteil Hohenfelde. Die fußläufig schnell erreichten U-Bahnstationen Wartenau und …', 'Das zentral gelegene Büro- und Geschäftsgebäude befindet sich nahe des Marienkankenhauses im Stadtteil Hohenfelde. Die fußläufig schnell erreichten U-Bahnstationen Wartenau und Lübecker Straße sichern eine sehr gute Anbindung an den ÖPNV. Die vielseitigen Einkaufsmöglichkeiten und diverse Cafés und Restaurants prägen das unmittelbare Umfeld. Die helle Bürofläche ist bereits ausgebaut und bietet auf Grund der flexiblen Raumaufteilung vielfältige Nutzungsmöglichkeiten. Die Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_23053.pdf', null, 'filemaker', '23053') on conflict (id) do nothing;
