insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25168')::uuid, md5('building-schellerdamm-22-28-21079')::uuid, '25168', 'der-channel-im-harburger-binnenhafen-25168', 'Der Channel im Harburger Binnenhafen', 'Der Channel 5-7 besteht aus drei miteinander verbundenen Gebäuden, die 1998 kernsaniert wurden. Sie befinden sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer …', 'Der Channel 5-7 besteht aus drei miteinander verbundenen Gebäuden, die 1998 kernsaniert wurden. Sie befinden sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 und A7 sowie die Harburger Altstadt. Die Gebäude sind vier- bis sechsgeschossig und verfügen über eine zentrale Lobby im Erdgeschoss. Die geplante Ausstattung der Bürofläche soll unter anderem eine Grundbeleuchtung, einen hochwertigen Bodenbelag, innenliegenden Blendschutz, eine funktionale Teeküche und separate sanitäre Einheiten umfassen. Die weitere Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenbilder sind beispielhaft gewählt und stammen aus einer anderen Mietfläche auf dem Gelände. PKW-Stellplätze können nach Absprache auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 260, 1600, 'https://www.buerohamburg.de/objects/pdf/BHI_25168.pdf', null, 'filemaker', '25168') on conflict (id) do nothing;
