insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24722')::uuid, md5('building-barnerstrasse-14-22765')::uuid, '24722', 'moderne-bueroflaeche-im-herzen-von-ottensen-24722', 'Moderne Bürofläche im Herzen von Ottensen', 'Der angebotene Bürokomplex befindet sich inmitten von Ottensen an der Barnerstraße. Das Umfeld ist geprägt durch zahlreiche Geschäfte des täglichen Bedarfs sowie eine Vielzahl an …', 'Der angebotene Bürokomplex befindet sich inmitten von Ottensen an der Barnerstraße. Das Umfeld ist geprägt durch zahlreiche Geschäfte des täglichen Bedarfs sowie eine Vielzahl an Cafés und Restaurants. Der Bahnhof Altona, mit diversen Anschlüssen an U- und S-Bahn, ist nach wenigen Fußminuten erreicht. Das moderne Gebäude wird über einen begrünten Innenhof und via Personenaufzug erschlossen. Zur zukünftigen Ausstattung der hellen Bürofläche zählen ein Hohlraumboden mit Bodentanks, Fußbodenbelag, Stehleuchten, fast bodentiefe Fenster, teilweise außen liegender elektrischer Sonnenschutz, moderne WC-Einheiten und eine hochwertige Pantry. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Die Innenansichten stammen aus einer ausgebauten Nachbarfläche.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 400, 1276, 'https://www.buerohamburg.de/objects/pdf/BHI_24722.pdf', null, 'filemaker', '24722') on conflict (id) do nothing;
