insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19184')::uuid, md5('building-borselstrasse-18-22765')::uuid, '19184', 'bueroflaeche-fuer-kreative-im-lebendigen-ottensen-19184', 'Bürofläche für Kreative im lebendigen Ottensen', 'Der Borselhof befindet sich inmitten des lebendigen, kreativen Stadtteils Ottensen zwischen den S-Bahn-Stationen Ottensen und Altona, nahe den Zeisehallen und der Fabrik. Das …', 'Der Borselhof befindet sich inmitten des lebendigen, kreativen Stadtteils Ottensen zwischen den S-Bahn-Stationen Ottensen und Altona, nahe den Zeisehallen und der Fabrik. Das Umfeld ist geprägt durch zahlreiche Geschäfte des täglichen Bedarfs sowie diverse Cafés und Restaurants. Die ehemaligen Fabrikhallen wurden mit viel Liebe zum Detail zu großzügigen Büroflächen umgebaut. Die loftartige Fläche wird über ein helles Treppenhaus mit Personenaufzug erschlossen und besticht durch hohe Decken sowie die Kombination von Sichtbalken und Stahlträgern. Zur Ausstattung zählen u.a. Dielen- und Teppichfußboden, hohe Decken, Beleuchtungssysteme, teilweise Einbauschänke, eine Pantry sowie getrennte WC-Einheiten.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-19184-1')::uuid, md5('property-19184')::uuid, 'Mietfläche', 404, 13.9, null, 'filemaker', '19184-1') on conflict (id) do nothing;
