insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20611')::uuid, md5('building-alter-teichweg-23a-22081')::uuid, '20611', 'schoenes-arbeiten-mit-blick-auf-den-osterbekkanal-20611', 'Schönes Arbeiten mit Blick auf den Osterbekkanal', 'Der moderne Neubau befindet sich in idyllischer Lage nahe dem Osterbekkanal im Stadtteil Barmbek-Nord. Der U- und S-Bahnhof Barmbek, mit zahlreichen Anschlüssen an das Bus-, U- …', 'Der moderne Neubau befindet sich in idyllischer Lage nahe dem Osterbekkanal im Stadtteil Barmbek-Nord. Der U- und S-Bahnhof Barmbek, mit zahlreichen Anschlüssen an das Bus-, U- und S-Bahnnetz, liegt nur wenige Fußminuten entfernt. Auch die Fuhlsbüttler Straße, mit allen Geschäften des täglichen Bedarfs und zahlreichen gastronomischen Angeboten, ist nach kurzem Fußweg erreicht erreicht.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-20611-1')::uuid, md5('property-20611')::uuid, 'Mietfläche', 404, 16.5, null, 'filemaker', '20611-1') on conflict (id) do nothing;
