insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8855')::uuid, md5('building-werner-siemens-strasse-70-22113')::uuid, '8855', 'funktionale-buero-und-lagerflaechen-in-verkehrsguenstiger-lage-8855', 'Funktionale Büro- und Lagerflächen in verkehrsgünstiger Lage', 'Das Bürogebäude befindet sich im Hamburger Industrie- und Gewerbegebiet Billbrook, in verkehrsgünstiger Lage zu den Autobahnen 1 und 25. Im Jahr 2010 wurde eine umfangreiche …', 'Das Bürogebäude befindet sich im Hamburger Industrie- und Gewerbegebiet Billbrook, in verkehrsgünstiger Lage zu den Autobahnen 1 und 25. Im Jahr 2010 wurde eine umfangreiche Modernisierung durchgeführt, bei der unter anderem die Eingangsbereiche und Sanitäranlagen erneuert und eine elektromechanische Außenverschattung eingebaut wurden. Das Gebäude verfügt zudem über einen Lastenaufzug. Zur Ausstattung der großräumlichen Mietfläche zählt unter anderem Doppelfußboden, Einbauschränke sowie umlaufende Kabelkanäle. Der Mietpreis richtet sich nach den Ausbauwünschen des Mieters. PKW-Stellplätze können auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], 287, 760, 'https://www.buerohamburg.de/objects/pdf/BHI_8855.pdf', null, 'filemaker', '8855') on conflict (id) do nothing;
