insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23369')::uuid, md5('building-kuehnehoefe-1-5-22761')::uuid, '23369', 'moderne-bueroflaeche-in-den-kuehnehoefen-mit-terrasse-23369', 'Moderne Bürofläche in den Kühnehöfen mit Terrasse', 'Das markante Büro- und Geschäftsgebäude befindet sich auf dem Areal der ehemaligen Essigfabrik der Carl Kühne KG. Das sechsgeschossige Bürohaus verfügt über beste …', 'Das markante Büro- und Geschäftsgebäude befindet sich auf dem Areal der ehemaligen Essigfabrik der Carl Kühne KG. Das sechsgeschossige Bürohaus verfügt über beste Verkehrsanbindungen zur A7 und den öffentlichen Verkehrsmitteln durch die S-Bahnstation Diebsteich und Ottensen sowie diverse Buslinien. Das Umfeld bietet viele Geschäfte des täglichen Bedarfs. Diese Bürofläche ist bereits ausgebaut. Zur hochwertigen Ausstattung zählt u.a. eine Kühldecke, ein Hohlraumboden, moderne WC-Einheiten, eine Teeküche und teilweise bodentiefe Fenster, Deckenfluter sowie außenliegender elektrischer Sonnenschutz. Highlight ist eine großzügige Terrasse mit einer Fläche von ca. 36 qm welche mit 8,50 € pro Quadratmeter zur Gesamtmiete hinzugerechnet wird. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], 295, 1129, 'https://www.buerohamburg.de/objects/pdf/BHI_23369.pdf', null, 'filemaker', '23369') on conflict (id) do nothing;
