insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24223')::uuid, md5('building-winterhuder-weg-62-68-22085')::uuid, '24223', 'moderne-bueroflaeche-in-beliebter-lage-von-winterhude-24223', 'Moderne Bürofläche in beliebter Lage von Winterhude', 'Der moderne Neubaukomplex, bestehend aus den beiden Gebäuden Red und Black, befindet sich aktuell in Erstellung und besticht durch seine zentrale Lage im Dreiländereck Winterhude, …', 'Der moderne Neubaukomplex, bestehend aus den beiden Gebäuden Red und Black, befindet sich aktuell in Erstellung und besticht durch seine zentrale Lage im Dreiländereck Winterhude, Barmbek-Süd und Uhlenhorst. Das direkte Umfeld ist geprägt durch alle Geschäfte des täglichen Bedarfs, eine Vielzahl an Restaurants und kleinen süßen Cafés. Die Anbindung an das öffentliche Verkehrsnetz ist durch den nahe gelegenen U-Bahnhof Mundsburg sowie diverse Buslinien am Objekt gesichert.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24223-1')::uuid, md5('property-24223')::uuid, 'Mietfläche', 408, 23, null, 'filemaker', '24223-1') on conflict (id) do nothing;
