insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23797')::uuid, md5('building-grosser-burstah-29-31-20457')::uuid, '23797', 'altstadt-hochmoderne-bueroflaeche-im-historischen-hindenburghaus-23797', 'Altstadt: Hochmoderne Bürofläche im historischen Hindenburghaus', 'Das markante Büro- und Geschäftsgebäude befindet sich in bevorzugter Hamburger Innenstadtlage nahe dem Rathausmarkt. Das Objekt wurde kürzlich hochwertig saniert um neue Synergien …', 'Das markante Büro- und Geschäftsgebäude befindet sich in bevorzugter Hamburger Innenstadtlage nahe dem Rathausmarkt. Das Objekt wurde kürzlich hochwertig saniert um neue Synergien zu schaffen. Das lebendige Umfeld ist durch hochwertige Einzelhändler, alle Geschäfte des täglichen Bedarfs sowie eine Vielzahl gastronomischer Angebote geprägt. Der Anschluss an das öffentliche Verkehrsnetz ist durch die fußläufig schnell erreichten U- und S-Bahnstationen Stadthausbrücke und Rödingsmarkt gesichert. Die moderne Bürofläche erschließt sich über ein historisches Foyer mit zwei Personenaufzügen und einen Paternoster. Ausstattung und Aufteilung erfolgen in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei']::text[], 410, 420, 'https://www.buerohamburg.de/objects/pdf/BHI_23797.pdf', null, 'filemaker', '23797') on conflict (id) do nothing;
