insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25093')::uuid, md5('building-roentgenstrasse-28-22335')::uuid, '25093', 'moderne-bueroflaeche-im-hamburger-norden-25093', 'Moderne Bürofläche im Hamburger Norden', 'Das moderne Bürogebäude befindet sich im Hamburger Norden in unmittelbarer Nähe zum Flughafen und schnellem Anschluss zur A7-Auffahrt Schnelsen-Nord. Der nicht weit entfernte …', 'Das moderne Bürogebäude befindet sich im Hamburger Norden in unmittelbarer Nähe zum Flughafen und schnellem Anschluss zur A7-Auffahrt Schnelsen-Nord. Der nicht weit entfernte U-Bahnhof Ohlsdorf sowie diverse Bushaltestellen im Umfeld sorgen für eine gute Anbindung an das öffentliche Verkehrsnetz. Nach 10 Fußminuten erreitch man den Alsterdorfer Markt mit zahlreichen Cafés und Restaurants sowie allen Geschäften des täglichen Bedarfsinsert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25093-1')::uuid, md5('property-25093')::uuid, 'Mietfläche', 411, 12, null, 'filemaker', '25093-1') on conflict (id) do nothing;
