insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-6069')::uuid, md5('building-theodorstrasse-42-90-22761')::uuid, '6069', 'dachterrassenloft-im-traditionellen-westend-village-6069', 'Dachterrassenloft im traditionellen Westend-Village', 'Das Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten. Das ehemalige Fabrikgelände der British American Tobacco  aus …', 'Das Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten. Das ehemalige Fabrikgelände der British American Tobacco  aus dem 19. Jahrhundert hat sich nach beendeter Restaurierung im Jahre 1998 in eine Anlage verwandelt, die durch ihr einmaliges Ambiente besticht. Restaurants und Cafés sind fußläufig zu erreichen. Zur Ausstattung der Bürofläche zählt u.a. Hohlraumboden, Innenliegender Blendschutz, Sonnenschutzverglasung, hochwertiger Teppichboden, Cat Verkabelung, eine  Gegensprechanlage, eine Pantry sowie getrennte sanitäre Anlagen. PKW-Stellplätze können auf Anfrage angemietet werden. Die Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Mietfläche im Gebäude.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['balkon-terrasse', 'stellplaetze']::text[], 196, 4300, 'https://www.buerohamburg.de/objects/pdf/BHI_6069.pdf', null, 'filemaker', '6069') on conflict (id) do nothing;
