insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24883')::uuid, md5('building-kurze-muehren-20-20095')::uuid, '24883', 'moderne-bueroraeume-mit-balkon-in-bester-citylage-24883', 'Moderne Büroräume mit Balkon in bester Citylage', 'Das moderne Büro- und Geschäftsgebäude befindet sich in bester Geschäftslage zwischen Mönckebergstraße und Binnenalster. Das Umfeld ist geprägt durch alle Geschäfte des täglichen …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in bester Geschäftslage zwischen Mönckebergstraße und Binnenalster. Das Umfeld ist geprägt durch alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants. Die helle Bürofläche wird über ein großzügiges Foyer mit zwei Personenaufzügen erschlossen. Zur aktuellen Ausstattung  zählen Teppichfußboden, Beleuchtungssysteme, bodentiefe Fenster, Bodentanks, elektrischer außen liegender Sonnenschutz, teilweise Glaselemente, akustisch wirksame Deckensegel, getrennte WC-Einheiten und eine moderne Pantry. Ein sonniger Balkon zum Innenhof ist vorhanden. Ein speziell entwickeltes Lüftungssystem sorgt außerdem für ein angenehmes Raumklima. Die Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 302, 413, 'https://www.buerohamburg.de/objects/pdf/BHI_24883.pdf', null, 'filemaker', '24883') on conflict (id) do nothing;
