insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-12385')::uuid, md5('building-hans-henny-jahnn-weg-29-33-22085')::uuid, '12385', 'helle-bueroflaeche-im-modernen-gebaeude-am-osterbekkanal-12385', 'Helle Bürofläche im modernen Gebäude am Osterbekkanal', 'Das repräsentative Bürohaus befindet sich im beliebten Stadtteil Uhlenhorst unmittelbar am schönen Osterbekkanal. Die Anbindung an den ÖPNV ist durch die Buslinien gegeben. Diese …', 'Das repräsentative Bürohaus befindet sich im beliebten Stadtteil Uhlenhorst unmittelbar am schönen Osterbekkanal. Die Anbindung an den ÖPNV ist durch die Buslinien gegeben. Diese sind ebenso wie diverse Geschäfte des täglichen Bedarfs und Restaurants im Mühlenkamp fußläufig schnell zu erreichen. Die Bürofläche verfügt u.a. über außenliegenden elektronischen Sonnenschutz, Teppichfußboden sowie getrennte WC-Einheiten. Eine Terrasse direkt am Kanal kann gemeinschaftlich genutzt werden. Die Bilder zeigen eine ähnliche Fläche im Objekt. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze', 'wasserblick']::text[], 344, 1602, 'https://www.buerohamburg.de/objects/pdf/BHI_12385.pdf', null, 'filemaker', '12385') on conflict (id) do nothing;
