insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25172')::uuid, md5('building-moenckebergstrasse-11-20095')::uuid, '25172', 'moderne-bueroflaeche-im-historischen-rappolt-haus-25172', 'Moderne Bürofläche im historischen Rappolt-Haus', 'Das repräsentative Rappolt-Haus befindet sich im Herzen der Hamburger Innenstadt nahe der Binnenalster an der bekannten Mönckebergstraße. Im direkten Umfeld findet man alle …', 'Das repräsentative Rappolt-Haus befindet sich im Herzen der Hamburger Innenstadt nahe der Binnenalster an der bekannten Mönckebergstraße. Im direkten Umfeld findet man alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants. Auch die Anbindung an das öffentliche Verkehrsnetz ist durch die nur wenige Meter entfernten U- und S-Bahnstationen Mönckebergstraße und Jungfernstieg sowie durch zahlreiche Buslinien gesichert. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25172-1')::uuid, md5('property-25172')::uuid, 'Mietfläche', 416, 23.5, null, 'filemaker', '25172-1') on conflict (id) do nothing;
