insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25008')::uuid, md5('building-haferweg-22-26-22769')::uuid, '25008', 'individuelle-bueroflaeche-in-markanter-ecklage-25008', 'Individuelle Bürofläche in markanter Ecklage', 'Der 1993 erbaute Kieler Park befindet sich in gut erreichbarer Lage im Hamburger Stadtteil Altona-Nord. Die S-Bahnstation Diebsteich ist schnell erreicht und bietet eine gute …', 'Der 1993 erbaute Kieler Park befindet sich in gut erreichbarer Lage im Hamburger Stadtteil Altona-Nord. Die S-Bahnstation Diebsteich ist schnell erreicht und bietet eine gute Anbindung an den ÖPNV. Das moderne Bürogebäude vereint Effizienz und Repräsentativität und eignet sich ideal für unterschiedlichste Unternehmen. Mit vier individuell gestalteten Erschließungskernen, jeweils mit repräsentativen Foyers, Empfangsbereichen und Treppenhäusern mit Personenaufzügen, bietet das Gebäude eine hohe Flexibilität und unterstützt eine klare Adressbildung. Große Fensterfronten sorgen für optimale Lichtverhältnisse. Die zukünftige Raumaufteilung und Ausstattung können in Absprache mit dem neuen Mieter gestaltet werden. PKW-Stellplätze stehen sowohl in der Tiefgarage als auch auf dem Gelände zur Anmietung bereit.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 418, 1816, 'https://www.buerohamburg.de/objects/pdf/BHI_25008.pdf', null, 'filemaker', '25008') on conflict (id) do nothing;
