insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23365')::uuid, md5('building-amsinckstrasse-32-20097')::uuid, '23365', 'klostertor-moderne-bueroflaeche-in-der-city-sued-mit-dachterrasse-23365', 'Klostertor: Moderne Bürofläche in der City-Süd mit Dachterrasse', 'Das Kontor 4 befindet sich in verkehrsgünstiger Lage zwischen den Elbbrücken und der Hamburger City. Der nahe gelegene Sonnin- und Mittelkanal, die Innenstadt sowie die …', 'Das Kontor 4 befindet sich in verkehrsgünstiger Lage zwischen den Elbbrücken und der Hamburger City. Der nahe gelegene Sonnin- und Mittelkanal, die Innenstadt sowie die Anbindungen an den ÖPNV über die S-Bahnstation Hammerbrook sind fußläufig erreichbar. Die Büroflächen werden über einen repräsentativen Eingangsbereich erschlossen und verfügen u.a. über außenliegenden Sonnenschutz, Teppichboden, Beleuchtung, Hohlraumböden, teilweise Glastrennwände, eine Küche und getrennte sanitäre Anlagen. Ein begrünter Innenhof lädt zum Verweilen in den Pausen ein. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], 355, 755, 'https://www.buerohamburg.de/objects/pdf/BHI_23365.pdf', null, 'filemaker', '23365') on conflict (id) do nothing;
