insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24360')::uuid, md5('building-caffamacherreihe-5-7-20355')::uuid, '24360', 'das-brahms-quartier-hochwertige-bueroflaechen-im-herzen-der-stadt-24360', 'Das Brahms Quartier: Hochwertige Büroflächen im Herzen der Stadt', 'Das moderne Büro- und Geschäftsgebäude befindet sich in erstklassiger City-Lage, nur wenige Meter vom Gänsemarkt entfernt. Eine Vielzahl an Einkaufsmöglichkeiten, Cafés und …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in erstklassiger City-Lage, nur wenige Meter vom Gänsemarkt entfernt. Eine Vielzahl an Einkaufsmöglichkeiten, Cafés und Restaurants prägen das lebendige Umfeld und sorgen für eine attraktive Arbeitsatmosphäre. Die nahe gelegenen U- und S-Bahnstationen Gänsemarkt und Jungfernstieg gewährleisten eine hervorragende Anbindung an den öffentlichen Nahverkehr.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24360-1')::uuid, md5('property-24360')::uuid, 'Mietfläche', 421, 23, null, 'filemaker', '24360-1') on conflict (id) do nothing;
